import { vec3 } from 'gl-matrix';
import { Sampler, along } from './volume';

const NB_ANGLES = 48; // directions measured around the axis

// Distances in mm
const SAFETY_MARGIN = 2;
const MAX_RADIUS = 4;

const MIN_DIAMETER = 3;
const MAX_LENGTH = 25;
// The bone walls are not checked in the first mm under the crest, which is irregular
const CREST_TOLERANCE = 1;

type Slice = {
  boneRadius: number;
  obstacleRadius: number;
  // The bone radius is set by the end of the volume, not by the anatomy
  boneLimitedByVolume: boolean;
};

// Radius available to place the implant at one depth: bone and tooth to replace, up to an obstacle, a cavity or the volume end
const measureSlice = (
  sample: Sampler,
  isToothPart: Uint8Array,
  boneIdx: number,
  isObstacle: Uint8Array,
  isCavity: Uint8Array,
  center: vec3,
  u: vec3,
  w: vec3,
  radialStep: number
): Slice => {
  let boneRadius = MAX_RADIUS;
  let obstacleRadius = MAX_RADIUS + SAFETY_MARGIN;
  let boneLimitedByVolume = false;
  const side = vec3.create();
  const point = vec3.create();
  const sampleAt = (distance: number) => sample(vec3.scaleAndAdd(point, center, side, distance));
  for (let a = 0; a < NB_ANGLES; a++) {
    const angle = (2 * Math.PI * a) / NB_ANGLES;
    vec3.scale(side, u, Math.cos(angle));
    vec3.scaleAndAdd(side, side, w, Math.sin(angle));

    let lastHealed = -radialStep;
    let stop = Infinity;
    let stopIsVolume = false;
    for (let distance = 0; distance < obstacleRadius; distance += radialStep) {
      const label = sampleAt(distance);
      if (isObstacle[label]) {
        obstacleRadius = distance;
        break;
      }
      // Past a cavity the obstacles are still searched
      if (stop !== Infinity) {
        continue;
      }
      if (label < 0 || isCavity[label]) {
        stop = distance;
        stopIsVolume = label < 0;
      } else if (isToothPart[label] || label === boneIdx) {
        lastHealed = distance;
      }
    }

    const rayRadius = lastHealed + radialStep;
    if (rayRadius < boneRadius) {
      boneRadius = rayRadius;
      boneLimitedByVolume = stopIsVolume && stop - rayRadius < radialStep / 2;
    }
  }
  return { boneRadius, obstacleRadius, boneLimitedByVolume };
};

// Max length where the narrowest implant still fits, usable radius at each depth down to it, and
// whether the max length is set by the end of the volume (the real one is then unknown)
const getImplantLimits = (
  sample: Sampler,
  isToothPart: Uint8Array,
  boneIdx: number,
  isObstacle: Uint8Array,
  isCavity: Uint8Array,
  entry: vec3,
  axis: vec3,
  [u, w]: vec3[],
  step: number,
  radialStep: number
) => {
  const nbMargin = Math.round(SAFETY_MARGIN / step);
  const nbDepths = Math.round(MAX_LENGTH / step) + 1;
  const sliceCenter = vec3.create();
  const slices = Array.from({ length: nbDepths + nbMargin }, (_, i) =>
    measureSlice(
      sample,
      isToothPart,
      boneIdx,
      isObstacle,
      isCavity,
      along(sliceCenter, entry, axis, i * step, u, 0),
      u,
      w,
      radialStep
    )
  );

  // The obstacles of the slices within SAFETY_MARGIN along the axis also count, at their 3D
  // distance: an obstacle dz above or below must be sqrt(margin² - dz²) away in the plane
  const getRadius = (i: number) => {
    const boneChecked = i * step >= CREST_TOLERANCE;
    let radius = boneChecked ? slices[i].boneRadius : MAX_RADIUS;
    let limitedByVolume = boneChecked && slices[i].boneLimitedByVolume;
    for (let j = Math.max(0, i - nbMargin); j <= i + nbMargin; j++) {
      const dz = (j - i) * step;
      const margin = Math.sqrt(Math.max(0, SAFETY_MARGIN * SAFETY_MARGIN - dz * dz));
      const obstacleLimit = slices[j].obstacleRadius - margin;
      if (obstacleLimit < radius) {
        radius = obstacleLimit;
        limitedByVolume = false;
      }
    }
    return { radius, limitedByVolume };
  };

  let nbFitting = 0;
  while (nbFitting < nbDepths && 2 * getRadius(nbFitting).radius >= MIN_DIAMETER) {
    nbFitting++;
  }
  const fits = nbFitting > 1;

  const limitedByVolume = nbFitting < nbDepths && getRadius(nbFitting).limitedByVolume;

  return {
    maxLength: fits ? (nbFitting - 1) * step : 0,
    limitedByVolume,
    radiusByDepth: Array.from({ length: nbFitting }, (_, i) => getRadius(i).radius),
    depthStep: step,
  };
};

export { getImplantLimits };
