import { vec3 } from 'gl-matrix';
import { SVD } from 'svd-js';
import { Types as cstTypes } from '@cornerstonejs/tools';
import { isMandibular, getNeighborTeeth, findSegment } from '../teeth';

// Very different roots need 5 passes to converge
const ROOT_AXIS_PASSES = 5;

// Mean of scatter plot
const getMean = (points: vec3[]) => {
  const mean = vec3.create();
  if (points.length === 0) {
    return mean;
  }
  points.forEach(point => vec3.add(mean, mean, point));
  return vec3.scale(mean, mean, 1 / points.length);
};

// Axis of the points, oriented toward the apex. Among the principal directions, the closest to
// the vertical is kept: a molar can be wider than long
const getApicalAxis = (points: vec3[], toothNumber: number) => {
  const mean = getMean(points);
  const covariance = [
    [0, 0, 0],
    [0, 0, 0],
    [0, 0, 0],
  ];
  const d = vec3.create();
  points.forEach(point => {
    vec3.sub(d, point, mean);
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        covariance[i][j] += d[i] * d[j];
      }
    }
  });
  const { v } = SVD(covariance);
  const directions = [0, 1, 2].map(k => vec3.fromValues(v[0][k], v[1][k], v[2][k]));
  const axis = directions.reduce((best, dir) =>
    Math.abs(dir[2]) > Math.abs(best[2]) ? dir : best
  );
  vec3.normalize(axis, axis);
  // World +Z goes to the patient's head (LPS)
  const apicalZ = isMandibular(toothNumber) ? -1 : 1;
  if (axis[2] * apicalZ < 0) {
    vec3.negate(axis, axis);
  }
  return axis;
};

// Axis between the roots, oriented toward the apex.
// The axis of the whole points is wrong with several roots.
// The points are cut in 4 around the current axis, and the axes of the 4 parts are averaged. Same result with a single root
const getRootAxis = (points: vec3[], toothNumber: number, mesioDistal: vec3) => {
  const center = getMean(points);
  const d = vec3.create();
  let axis = getApicalAxis(points, toothNumber);
  for (let pass = 0; pass < ROOT_AXIS_PASSES; pass++) {
    const side = vec3.scaleAndAdd(vec3.create(), mesioDistal, axis, -vec3.dot(mesioDistal, axis));
    const otherSide = vec3.cross(vec3.create(), axis, side);
    const parts: vec3[][] = [[], [], [], []];
    points.forEach(point => {
      vec3.sub(d, point, center);
      parts[(vec3.dot(d, side) > 0 ? 1 : 0) + (vec3.dot(d, otherSide) > 0 ? 2 : 0)].push(point);
    });
    const sum = vec3.create();
    parts
      .filter(part => part.length >= 3)
      .forEach(part => vec3.add(sum, sum, getApicalAxis(part, toothNumber)));
    axis = vec3.normalize(vec3.create(), sum);
  }
  return axis;
};

// Centroid of the closest present tooth on one side along the arch
const findNeighborCentroid = (
  toothNumber: number,
  side: 'previous' | 'next',
  segments: { [segmentIndex: number]: cstTypes.Segment },
  getCentroid: (label: number) => vec3 | undefined
) => {
  for (
    let n = getNeighborTeeth(toothNumber)[side];
    n !== undefined;
    n = getNeighborTeeth(n)[side]
  ) {
    const segment = findSegment(segments, n);
    const centroid = segment && getCentroid(segment.segmentIndex);
    if (centroid) {
      return centroid;
    }
  }
  return undefined;
};

// Unit direction toward the neighbors along the arch, perpendicular to the axis
const getMesioDistal = (axis: vec3, center: vec3, previous?: vec3, next?: vec3) => {
  if (!previous && !next) {
    return undefined;
  }
  const direction =
    previous && next
      ? vec3.sub(vec3.create(), next, previous)
      : vec3.sub(vec3.create(), previous ?? next, center);
  vec3.scaleAndAdd(direction, direction, axis, -vec3.dot(direction, axis));
  return vec3.normalize(direction, direction);
};

// Two unit directions perpendicular to the axis and to each other.
const getPerpendicularBasis = (axis: vec3) => {
  const start = Math.abs(axis[0]) < 0.9 ? vec3.fromValues(1, 0, 0) : vec3.fromValues(0, 1, 0);
  const u = vec3.scaleAndAdd(vec3.create(), start, axis, -vec3.dot(start, axis));
  vec3.normalize(u, u);
  const w = vec3.cross(vec3.create(), axis, u);
  return [u, w];
};

export {
  getMean,
  getApicalAxis,
  getRootAxis,
  findNeighborCentroid,
  getMesioDistal,
  getPerpendicularBasis,
};
