import { vec3 } from 'gl-matrix';
import { Sampler, along } from './volume';
import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';

// Distances in mm

// Max distance from the implant axis to a neighbor root
const GAP_SEARCH = 10;
// Half length of the tooth line where the bone section is searched
const BONE_SEARCH = 10;
// A non-bone run shorter than this is a hole in the mask, not the end of the bone
const HOLE_TOLERANCE = 1;
// Depths under the entry where the position is measured: just under the irregular crest
const POSITION_DEPTHS: NumberPair = [1, 3];
// Depths under the entry where the orientation is measured
const ORIENTATION_DEPTHS: NumberPair = [1, 8];

// Offsets from the axis to the center of the gap, [depth, offset] for each measured depth
type CenterSamples = {
  mesioDistal: NumberPair[];
  buccoLingual: NumberPair[];
};

// Distance from the origin to the first voxel of the label in one direction
const findLabel = (
  sample: Sampler,
  label: number,
  origin: vec3,
  side: vec3,
  radialStep: number
) => {
  const point = vec3.create();
  for (let distance = 0; distance <= GAP_SEARCH; distance += radialStep) {
    if (sample(vec3.scaleAndAdd(point, origin, side, distance)) === label) {
      return distance;
    }
  }
  return undefined;
};

// Offset from the origin to the middle of the closest bone section.
const findBoneMiddle = (
  sample: Sampler,
  boneIdx: number,
  origin: vec3,
  side: vec3,
  radialStep: number
) => {
  const point = vec3.create();
  const nbSteps = Math.round((2 * BONE_SEARCH) / radialStep);
  const sections: NumberPair[] = [];
  let start: number | undefined;
  let lastBone = 0;
  for (let i = 0; i <= nbSteps; i++) {
    const t = -BONE_SEARCH + i * radialStep;
    if (sample(vec3.scaleAndAdd(point, origin, side, t)) === boneIdx) {
      start ??= t;
      lastBone = t;
    } else if (start !== undefined && t - lastBone > HOLE_TOLERANCE) {
      sections.push([start, lastBone]);
      start = undefined;
    }
  }

  let middle: number | undefined;
  let closest = Infinity;
  sections
    .filter(([sectionStart]) => sectionStart > -BONE_SEARCH)
    .forEach(([sectionStart, sectionEnd]) => {
      const distance = Math.max(sectionStart, -sectionEnd, 0);
      if (distance < closest) {
        closest = distance;
        middle = (sectionStart + sectionEnd) / 2;
      }
    });
  return middle;
};

// At each depth under the entry, offset to the middle of the two neighbor roots.
const measureCenters = (
  sample: Sampler,
  previousIdx: number,
  nextIdx: number,
  boneIdx: number,
  entry: vec3,
  axis: vec3,
  mesioDistal: vec3,
  buccoLingual: vec3,
  [minDepth, maxDepth]: NumberPair,
  step: number,
  radialStep: number
): CenterSamples => {
  const distoMesial = vec3.negate(vec3.create(), mesioDistal);
  const samples: CenterSamples = { mesioDistal: [], buccoLingual: [] };
  const point = vec3.create();
  for (let depth = minDepth; depth <= maxDepth; depth += step) {
    along(point, entry, axis, depth, mesioDistal, 0);

    let mesioDistalOffset = 0;
    const toPrevious = findLabel(sample, previousIdx, point, distoMesial, radialStep);
    const toNext = findLabel(sample, nextIdx, point, mesioDistal, radialStep);
    if (toPrevious !== undefined && toNext !== undefined) {
      mesioDistalOffset = (toNext - toPrevious) / 2;
      samples.mesioDistal.push([depth, mesioDistalOffset]);
    }

    // The bone is searched from the middle of the roots
    vec3.scaleAndAdd(point, point, mesioDistal, mesioDistalOffset);
    const buccoLingualOffset = findBoneMiddle(sample, boneIdx, point, buccoLingual, radialStep);
    if (buccoLingualOffset !== undefined) {
      samples.buccoLingual.push([depth, buccoLingualOffset]);
    }
  }
  return samples;
};

const getBuccoLingual = (axis: vec3, mesioDistal: vec3) =>
  vec3.normalize(vec3.create(), vec3.cross(vec3.create(), axis, mesioDistal));

const getMeanOffset = (samples: NumberPair[]) =>
  samples.length > 0 ? samples.reduce((sum, [, offset]) => sum + offset, 0) / samples.length : 0;

// Least squares slope of offset = slope * depth: the line goes through the entry
const getSlope = (samples: NumberPair[]) => {
  let depthOffset = 0;
  let depthDepth = 0;
  samples.forEach(([depth, offset]) => {
    depthOffset += depth * offset;
    depthDepth += depth * depth;
  });
  return depthDepth > 0 ? depthOffset / depthDepth : 0;
};

// Entry moved, at the same depth, to the middle of the roots and of the bone just under the crest.
const centerEntry = (
  sample: Sampler,
  previousIdx: number,
  nextIdx: number,
  boneIdx: number,
  entry: vec3,
  axis: vec3,
  mesioDistal: vec3,
  step: number,
  radialStep: number
) => {
  const buccoLingual = getBuccoLingual(axis, mesioDistal);
  const samples = measureCenters(
    sample,
    previousIdx,
    nextIdx,
    boneIdx,
    entry,
    axis,
    mesioDistal,
    buccoLingual,
    POSITION_DEPTHS,
    step,
    radialStep
  );
  const centered = vec3.scaleAndAdd(
    vec3.create(),
    entry,
    mesioDistal,
    getMeanOffset(samples.mesioDistal)
  );
  return vec3.scaleAndAdd(centered, centered, buccoLingual, getMeanOffset(samples.buccoLingual));
};

// Axis tilted, around the entry, to follow the middle of the roots and of the bone in depth.
const followBone = (
  sample: Sampler,
  previousIdx: number,
  nextIdx: number,
  boneIdx: number,
  entry: vec3,
  axis: vec3,
  mesioDistal: vec3,
  step: number,
  radialStep: number
) => {
  const buccoLingual = getBuccoLingual(axis, mesioDistal);
  const samples = measureCenters(
    sample,
    previousIdx,
    nextIdx,
    boneIdx,
    entry,
    axis,
    mesioDistal,
    buccoLingual,
    ORIENTATION_DEPTHS,
    step,
    radialStep
  );
  const tilted = vec3.scaleAndAdd(vec3.create(), axis, mesioDistal, getSlope(samples.mesioDistal));
  vec3.scaleAndAdd(tilted, tilted, buccoLingual, getSlope(samples.buccoLingual));
  return vec3.normalize(tilted, tilted);
};

export { centerEntry, followBone };
