import { vec3 } from 'gl-matrix';
import vtkImageData from '@kitware/vtk.js/Common/DataModel/ImageData';
import { Vector3 } from '@kitware/vtk.js/types';
import { Types as cstTypes } from '@cornerstonejs/tools';
import { SVD } from 'svd-js';
import { IVoxelManager, Point3 } from '@cornerstonejs/core/types';
import { isMandibular, getNeighborTeeth, findSegment } from '../teeth';
import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';

// Old version of the placement between two neighbor teeth (index space), kept for reference

// Bone segment indices in the anatomy segmentation
// TODO: read them from the anatomy labels
const MANDIBULAR_IDX = 1;
const MAXILLAR_IDX = 2;

// [z, y, x] of every voxel of a segment, searched only within the teeth layers
const findIndices = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  value: number,
  [minTissueLayer, maxTissueLayer]: NumberPair
) => {
  const indices: number[][] = [];
  const [layerWidth, layerHeight] = dimensions;
  const layerSize: number = layerWidth * layerHeight;
  for (let layer = minTissueLayer; layer <= maxTissueLayer; layer++) {
    const baseIndex = layer * layerSize;
    for (let y = 0; y < layerHeight; y++) {
      const rowIndex = baseIndex + y * layerWidth;
      for (let x = 0, idx = rowIndex; x < layerWidth; x++, idx++) {
        if (scalarData[idx] === value) {
          indices.push([layer, y, x]);
        }
      }
    }
  }
  return indices;
};

// Principal axis of a tooth (SVD), going through its center
const calculateToothAxis = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  toothIdx: number,
  minMaxTissueLayer: NumberPair
) => {
  const points = findIndices(scalarData, dimensions, toothIdx, minMaxTissueLayer);
  if (points.length === 0) {
    return;
  }

  const mean = [0, 1, 2].map(i => points.reduce((sum, p) => sum + p[i], 0) / points.length);
  const centered = points.map(p => p.map((v, i) => v - mean[i]));
  // The principal direction is the first column of v
  const { v } = SVD(centered);
  const direction = v.map(row => row[0]);
  const norm = Math.sqrt(direction.reduce((sum, d) => sum + d * d, 0));
  const [vz, vy, vx] = direction.map(d => d / norm);
  const [z0, y0, x0] = mean;

  return [vz, vy, vx, z0, y0, x0];
};

// Implant axis = average of the two neighbor teeth axes
const getAxis = (
  segVoxelManager: IVoxelManager<number>,
  segments: { [segmentIndex: number]: cstTypes.Segment },
  toothNumber: number,
  minMaxTissueLayer: NumberPair
) => {
  const { previous, next } = getNeighborTeeth(toothNumber);
  const previousSegment = findSegment(segments, previous);
  const nextSegment = findSegment(segments, next);
  if (!previousSegment || !nextSegment) {
    return undefined;
  }
  const scalarData = segVoxelManager.getCompleteScalarDataArray();
  const { dimensions } = segVoxelManager;
  const previousAxis = calculateToothAxis(
    scalarData,
    dimensions,
    previousSegment.segmentIndex,
    minMaxTissueLayer
  );
  const nextAxis = calculateToothAxis(
    scalarData,
    dimensions,
    nextSegment.segmentIndex,
    minMaxTissueLayer
  );

  if (!previousAxis && !nextAxis) {
    return undefined;
  }
  if (!previousAxis || !nextAxis) {
    return previousAxis ?? nextAxis;
  }
  return previousAxis.map((v, i) => (v + nextAxis[i]) / 2);
};

// Walk along the axis from the crown side and return the first t that hits the bone
const findStart = (
  segVoxelManager: IVoxelManager<number>,
  toothNumber: number,
  axis: number[],
  minMaxTissueLayer: NumberPair
) => {
  const [layerWidth, layerHeight, nbLayers] = segVoxelManager.dimensions;
  const [vz, vy, vx, z0, y0, x0] = axis;
  const getXYZ = (t: number): Vector3 => [
    Math.floor(x0 + t * vx),
    Math.floor(y0 + t * vy),
    Math.floor(z0 + t * vz),
  ];
  const inBounds = (x: number, y: number, z: number) =>
    x >= 0 && x < layerWidth && y >= 0 && y < layerHeight && z >= 0 && z < nbLayers;
  const mandibular = isMandibular(toothNumber);
  const boneIdx = mandibular ? MANDIBULAR_IDX : MAXILLAR_IDX;
  const step = mandibular ? -1 : 1;

  let tMin = Math.ceil((minMaxTissueLayer[0] - z0) / vz);
  let tMax = Math.ceil((minMaxTissueLayer[1] - z0) / vz);
  if (mandibular) {
    // Top-down for mandibular and bottom-up for maxillar
    [tMin, tMax] = [tMax, tMin];
  }

  let tStart = tMin;
  for (; tStart !== tMax; tStart += step) {
    const [x, y, z] = getXYZ(tStart);
    if (!inBounds(x, y, z)) {
      continue;
    }
    if (segVoxelManager.getAtIJK(x, y, z) === boneIdx) {
      break;
    }
  }

  return tStart !== tMax ? tStart : undefined;
};

// Convert the implant placement from index space to world space
const getImplantPose = (
  toothNumber: number,
  axis: number[],
  tStart: number,
  imageData: vtkImageData
) => {
  const [vz, vy, vx, z0, y0, x0] = axis;
  const sign = isMandibular(toothNumber) ? -1 : 1;

  const startIJK: Vector3 = [x0 + tStart * vx, y0 + tStart * vy, z0 + tStart * vz];
  const apexIJK: Vector3 = [
    startIJK[0] + sign * vx,
    startIJK[1] + sign * vy,
    startIJK[2] + sign * vz,
  ];
  const position = imageData.indexToWorld(startIJK) as Vector3;
  const apex = imageData.indexToWorld(apexIJK) as Vector3;

  const direction = vec3.sub(vec3.create(), apex, position);
  vec3.normalize(direction, direction);
  const dir = [direction[0], direction[1], direction[2]] as Vector3;

  return { position: position, direction: dir };
};

export { getAxis, findStart, getImplantPose };
