import React, { useEffect, useState } from 'react';
import { WediagSelect } from '@ohif/ui';
import { IMPLANT_CATALOG, getImplantModelKey } from './implants';
import { ImplantModel } from '../types/Panoramic';

const sortStrings = (values: string[]) => [...new Set(values)].sort();
const sortNumbers = (values: number[]) => [...new Set(values)].sort((a, b) => a - b);

// Value of the list closest to the wanted one, the first one if there is no wanted value
const getClosest = (values: number[], wanted?: number) =>
  wanted === undefined
    ? values[0]
    : values.reduce((closest, v) =>
        Math.abs(v - wanted) < Math.abs(closest - wanted) ? v : closest
      );

// Options of every field for the selected model
const getOptions = (model: ImplantModel) => {
  const brandModels = IMPLANT_CATALOG.filter(m => m.brand === model.brand);
  const familyModels = brandModels.filter(m => m.family === model.family);
  const diameterModels = familyModels.filter(m => m.diameter === model.diameter);
  return {
    brands: sortStrings(IMPLANT_CATALOG.map(m => m.brand)),
    families: sortStrings(brandModels.map(m => m.family)),
    diameters: sortNumbers(familyModels.map(m => m.diameter)),
    lengths: sortNumbers(diameterModels.map(m => m.length)),
    references: diameterModels.filter(m => m.length === model.length),
  };
};

// Catalog model from the wanted fields. A missing field takes the first value of its list.
const findModel = ({
  brand,
  family,
  diameter,
  length,
}: {
  brand: string;
  family?: string;
  diameter?: number;
  length?: number;
}): ImplantModel => {
  const brandModels = IMPLANT_CATALOG.filter(m => m.brand === brand);
  const families = sortStrings(brandModels.map(m => m.family));
  const foundFamily = families.includes(family) ? family : families[0];

  const familyModels = brandModels.filter(m => m.family === foundFamily);
  const diameters = sortNumbers(familyModels.map(m => m.diameter));
  const foundDiameter = diameters.includes(diameter) ? diameter : diameters[0];

  const diameterModels = familyModels.filter(m => m.diameter === foundDiameter);
  const foundLength = getClosest(sortNumbers(diameterModels.map(m => m.length)), length);

  return diameterModels.find(m => m.length === foundLength);
};

// Selection of an implant model of the catalog.
const ImplantModelSelector = ({
  model,
  onChange,
}: {
  model: ImplantModel;
  onChange: (model: ImplantModel) => void;
}) => {
  const [selected, setSelected] = useState(model);

  const modelKey = getImplantModelKey(model);
  useEffect(() => setSelected(model), [modelKey]);

  const { brand, family, diameter, length } = selected;
  const { brands, families, diameters, lengths, references } = getOptions(selected);

  const select = (newModel: ImplantModel) => {
    setSelected(newModel);
    onChange(newModel);
  };

  // Several models can share a size (other surface or platform): the name tells them apart
  const getReferenceLabel = (m: ImplantModel) =>
    references.length > 1 ? `${m.id || '-'} (${m.name})` : m.id || '-';

  return (
    <div className="flex w-[90%] flex-col space-y-1">
      <div className="flex w-full space-x-2">
        <WediagSelect
          label="Brand"
          value={brand}
          options={brands.map(b => [b, b])}
          onChange={value => select(findModel({ brand: value }))}
        />
        <WediagSelect
          label="Model"
          value={family}
          options={families.map(f => [f, f])}
          onChange={value => select(findModel({ brand, family: value }))}
        />
      </div>

      <div className="flex w-full space-x-2">
        <WediagSelect
          label="Diameter"
          value={String(diameter)}
          options={diameters.map(d => [String(d), `Ø ${d} mm`])}
          onChange={value => select(findModel({ brand, family, diameter: +value, length }))}
        />
        <WediagSelect
          label="Length"
          value={String(length)}
          options={lengths.map(l => [String(l), `${l} mm`])}
          onChange={value => select(findModel({ brand, family, diameter, length: +value }))}
        />
      </div>

      <WediagSelect
        label="Reference"
        value={getImplantModelKey(selected)}
        options={references.map(m => [getImplantModelKey(m), getReferenceLabel(m)])}
        onChange={value => select(references.find(m => getImplantModelKey(m) === value))}
      />
    </div>
  );
};

export default ImplantModelSelector;
