import { vec3 } from 'gl-matrix';
import vtkImageData from '@kitware/vtk.js/Common/DataModel/ImageData';
import { Types as cstTypes } from '@cornerstonejs/tools';
import { IVoxelManager } from '@cornerstonejs/core/types';
import { isMandibular, isTooth } from '../teeth';
import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';

// Anatomy labels
const LOWER_BONE_LABEL = 'Lower Jawbone';
const UPPER_BONE_LABEL = 'Upper Jawbone';
const NERVE_LABEL = 'Nerve';
const PULP_LABEL = 'Pulp';
const SINUS_LABEL = 'Sinus';

interface Anatomy {
  segments: { [segmentIndex: number]: cstTypes.Segment };
  voxelManager: IVoxelManager<number>;
  imageData: vtkImageData;
}

// Label at a world point, -1 outside the volume
type Sampler = (point: vec3) => number;

const findSegmentIndex = (segments: { [segmentIndex: number]: cstTypes.Segment }, label: string) =>
  Object.values(segments).find(segment => segment?.label === label)?.segmentIndex;

const createSampler = ({ voxelManager, imageData }: Anatomy): Sampler => {
  const scalarData = voxelManager.getCompleteScalarDataArray();
  const [width, height, nbLayers] = voxelManager.dimensions;
  const worldToIndex = imageData.getWorldToIndex();
  const ijk = vec3.create();
  return point => {
    vec3.transformMat4(ijk, point, worldToIndex);
    const x = Math.round(ijk[0]);
    const y = Math.round(ijk[1]);
    const z = Math.round(ijk[2]);
    if (x < 0 || x >= width || y < 0 || y >= height || z < 0 || z >= nbLayers) {
      return -1;
    }
    return scalarData[x + y * width + z * width * height];
  };
};

// Start from the origin point, move down along the axis, then shift to the side by a certain distance.
const along = (
  out: vec3,
  origin: vec3,
  axis: vec3,
  depth: number,
  side: vec3,
  distance: number
) => {
  // out = origin + depth * axis + distance * side
  vec3.scaleAndAdd(out, origin, axis, depth);
  return vec3.scaleAndAdd(out, out, side, distance);
};

// One pass on the teeth layers: centroid (world) of every label and world points of the given teeth
const scanTeethLayers = (
  { voxelManager, imageData }: Anatomy,
  toothIdxs: number[],
  [minTissueLayer, maxTissueLayer]: NumberPair
) => {
  const scalarData = voxelManager.getCompleteScalarDataArray();
  const [width, height] = voxelManager.dimensions;
  const counts = new Float64Array(256);
  const sums = new Float64Array(256 * 3);
  const ijkByLabel = new Map<number, number[]>(toothIdxs.map(toothIdx => [toothIdx, []]));
  for (let z = minTissueLayer; z <= maxTissueLayer; z++) {
    for (let y = 0; y < height; y++) {
      for (let x = 0, idx = (z * height + y) * width; x < width; x++, idx++) {
        const label = scalarData[idx];
        if (!label) {
          continue;
        }
        counts[label]++;
        sums[label * 3] += x;
        sums[label * 3 + 1] += y;
        sums[label * 3 + 2] += z;
        ijkByLabel.get(label)?.push(x, y, z);
      }
    }
  }

  const indexToWorld = imageData.getIndexToWorld();
  const getCentroid = (label: number) => {
    if (!counts[label]) {
      return undefined;
    }
    const ijk = vec3.fromValues(sums[label * 3], sums[label * 3 + 1], sums[label * 3 + 2]);
    vec3.scale(ijk, ijk, 1 / counts[label]);
    return vec3.transformMat4(vec3.create(), ijk, indexToWorld);
  };
  const getPoints = (toothIdx: number) => {
    const toothIJK = ijkByLabel.get(toothIdx) ?? [];
    const toothPoints: vec3[] = [];
    for (let i = 0; i < toothIJK.length; i += 3) {
      const ijk = vec3.fromValues(toothIJK[i], toothIJK[i + 1], toothIJK[i + 2]);
      toothPoints.push(vec3.transformMat4(ijk, ijk, indexToWorld));
    }
    return toothPoints;
  };

  return { getCentroid, getPoints };
};

// Jawbone of the tooth in the anatomy segmentation
const findBoneIndex = (
  segments: { [segmentIndex: number]: cstTypes.Segment },
  toothNumber: number
) => findSegmentIndex(segments, isMandibular(toothNumber) ? LOWER_BONE_LABEL : UPPER_BONE_LABEL);

// Labels that must stay SAFETY_MARGIN away: the other teeth and the nerve
const getObstacles = (
  segments: { [segmentIndex: number]: cstTypes.Segment },
  toothNumber: number
) => {
  const isObstacle = new Uint8Array(256);
  Object.values(segments).forEach(segment => {
    const number = Number(segment?.label);
    if (segment && isTooth(number) && number !== toothNumber) {
      isObstacle[segment.segmentIndex] = 1;
    }
  });
  const nerveIdx = findSegmentIndex(segments, NERVE_LABEL);
  if (nerveIdx !== undefined) {
    isObstacle[nerveIdx] = 1;
  }
  return isObstacle;
};

// Labels of the tooth to place the implant: the tooth itself and the pulp
const getToothParts = (
  segments: { [segmentIndex: number]: cstTypes.Segment },
  toothIdx: number
) => {
  const isToothPart = new Uint8Array(256);
  isToothPart[toothIdx] = 1;
  const pulpIdx = findSegmentIndex(segments, PULP_LABEL);
  if (pulpIdx !== undefined) {
    isToothPart[pulpIdx] = 1;
  }
  return isToothPart;
};

// Labels that end the bone without margin: the sinus
const getCavities = (segments: { [segmentIndex: number]: cstTypes.Segment }) => {
  const isCavity = new Uint8Array(256);
  const sinusIdx = findSegmentIndex(segments, SINUS_LABEL);
  if (sinusIdx !== undefined) {
    isCavity[sinusIdx] = 1;
  }
  return isCavity;
};

export {
  findSegmentIndex,
  createSampler,
  along,
  scanTeethLayers,
  findBoneIndex,
  getObstacles,
  getToothParts,
  getCavities,
};
export type { Anatomy, Sampler };
